import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';import path from 'node:path';import crypto from 'node:crypto';
import * as T from '../static/vendor/three-0.160.1.module.js';import Scene from '../static/pet-town-scene.js';import Town from '../static/pet-town-walk.js';
import {build,spec,triangleBoxDistance} from '../static/pet-acorn-mail-slot-proof-20261027/slot-motion.mjs';import {placeAndProbe} from '../static/pet-acorn-mailbox-proof-20261027/placement.mjs';
const base=path.resolve(import.meta.dirname,'../static/pet-acorn-mail-slot-proof-20261027'),staticRoot=path.resolve(base,'..'),sha=z=>crypto.createHash('sha256').update(z).digest('hex'),near=(a,b,e=1e-7)=>assert.ok(Math.abs(a-b)<e,a+' != '+b);
test('the fixed mailbox recipe and original bytes are reused exactly and all ordinary-use gates remain false',()=>{assert.equal(sha(fs.readFileSync(path.join(staticRoot,'pet-acorn-mailbox-proof-20261027/mailbox.mjs'))),spec.mailboxSourceSHA);assert.equal(sha(fs.readFileSync(path.join(staticRoot,'pet-acorn-mailbox-proof-20261027/reference.png'))),spec.originalSHA);const m=build(T),p=m.inspect();assert.equal(m.mailbox.angle,0);assert.equal(p.bodyBinding,null);for(const k of ['actualDelivery','dropGravityFriction','characterGrip','normalPlacement','ownershipUnlockSave','continuousCollisionCertified','initialBlankCauseEstablished','initializationConsistencyVerified'])assert.equal(p[k],false,k);assert.equal(p.dimensionsNotPaperOrBodyMeasurements,true);m.dispose();});
test('the rigid envelope is a closed twelve-triangle solid and its actual vertex box matches the collision box in flat slot orientation',()=>{const m=build(T),g=m.body.geometry,p=g.attributes.position,ix=g.index,edges=new Map(),key=i=>[p.getX(i),p.getY(i),p.getZ(i)].map(x=>x.toFixed(7)).join(':');let volume=0;for(let i=0;i<ix.count;i+=3){const ids=[ix.getX(i),ix.getX(i+1),ix.getX(i+2)],[a,b,c]=ids.map(n=>new T.Vector3().fromBufferAttribute(p,n));assert.ok(b.clone().sub(a).cross(c.clone().sub(a)).lengthSq()>0);volume+=a.dot(b.clone().cross(c))/6;for(let j=0;j<3;j++){const a=key(ids[j]),b=key(ids[(j+1)%3]),k=[a,b].sort().join('|'),v=edges.get(k)||{n:0,d:0};v.n++;v.d+=a<b?1:-1;edges.set(k,v);}}assert.equal(ix.count/3,12);assert.ok(volume>0);assert.ok([...edges.values()].every(x=>x.n===2&&x.d===0));m.setProgress(.425);const box=new T.Box3().setFromObject(m.body,true),r=m.inspect().currentPose;for(let i=0;i<3;i++){near(box.min.toArray()[i],r.box.min[i]);near(box.max.toArray()[i],r.box.max[i]);}near(box.getSize(new T.Vector3()).y,.010);assert.deepEqual(m.body.rotation.toArray().slice(0,3),[0,0,0]);m.dispose();});
test('triangle-to-box clearance handles face separation, edge/edge separation and actual intersection',()=>{const b=new T.Box3(new T.Vector3(0,0,0),new T.Vector3(1,1,1));near(triangleBoxDistance(T,new T.Triangle(new T.Vector3(2,0,0),new T.Vector3(2,1,0),new T.Vector3(2,0,1)),b),1);near(triangleBoxDistance(T,new T.Triangle(new T.Vector3(2,2,0),new T.Vector3(3,2,0),new T.Vector3(2,3,0)),b),Math.SQRT2);near(triangleBoxDistance(T,new T.Triangle(new T.Vector3(.5,.5,-1),new T.Vector3(.5,.5,2),new T.Vector3(.5,2,.5)),b),0);});
test('twenty-one finite actual-mesh poses pass through the real slot with positive surface gap and no hidden solid containment',()=>{const m=build(T),c=m.certificate();assert.equal(c.samples,21);assert.equal(c.finiteSamplesAreNotUniqueTests,true);assert.equal(c.continuousCollisionCertified,false);assert.equal(c.allFinitePosesClear,true);near(c.minimumTriangleBoxGap,.0325);for(const p of c.poses){assert.equal(p.actualMailboxParts,57);assert.ok(p.actualMailboxTriangles>7000);assert.equal(p.hatchAngle,0);assert.deepEqual(p.surfaceIntersections,[]);assert.deepEqual(p.containedByParts,[]);}m.dispose();});
test('oversized, vertically thick and offset candidates are rejected by actual aperture/wall triangles without moving the visible envelope',()=>{const m=build(T);m.setProgress(.2);const before=m.body.position.toArray();for(const changes of [{width:.70},{thickness:.12},{x:.34},{y:1.65}]){const c=m.certificate(changes);assert.equal(c.allFinitePosesClear,false,JSON.stringify(changes));assert.ok(c.poses.some(p=>p.surfaceIntersections.length>0||p.containedByParts.length>0));}assert.deepEqual(m.body.position.toArray(),before);near(m.progress,.2);const embedded=m.evaluate(.5,{width:.01,thickness:.01,depth:.01,x:.45,y:1.29,startZ:.32,endZ:.32});assert.equal(embedded.clear,false);assert.ok(embedded.containedByParts.includes('front-wall-actual-door-and-slot-holes'));m.dispose();});
test('outside and inside endpoints are clear of the closed front, roof and back; opening the reused hatch invalidates the fixed-hatch proof',()=>{const m=build(T),out=m.evaluate(0),inside=m.evaluate(1),front=new T.Box3().setFromObject(m.mailbox.front,true),back=new T.Box3().setFromObject(m.mailbox.back,true);assert.ok(out.box.min[2]>front.max.z);assert.ok(inside.box.max[2]<front.min.z);assert.ok(inside.box.min[2]>back.max.z);assert.ok(inside.box.max[1]<new T.Box3().setFromObject(m.mailbox.roof,true).min.y);assert.equal(inside.clear,true);m.mailbox.setAngle(95);assert.throws(()=>m.evaluate(.5),/hatch_not_closed/);m.mailbox.setAngle(0);m.reset();m.dispose();});
test('manual fractional in/out/reverse/reset controls reject invalid values without allocating or changing pose',()=>{const m=build(T),resources=Object.fromEntries(Object.entries(m.resources).map(([k,v])=>[k,[...v]]));m.setProgress(.37625);m.step(.1);near(m.progress,.47625);m.step(-.2);near(m.progress,.27625);m.step(2);near(m.progress,1);m.step(-2);near(m.progress,0);for(const v of [NaN,Infinity,-.01,1.01,'0.5',null])assert.throws(()=>m.setProgress(v),/progress_invalid/);for(const v of ['1',NaN,null])assert.throws(()=>m.step(v),/step_invalid/);m.setProgress(.7);m.reset();near(m.progress,0);for(const [k,v]of Object.entries(resources))assert.deepEqual([...m.resources[k]],v);m.dispose();});
test('the extended envelope uses actual floor/path/card probes in the unchanged original-art village without becoming a walkable or owned item',()=>{const world=Town.createWorld(),before=JSON.stringify(world),model=Scene.buildWorld(T,world,{},null,null,'autumn'),m=build(T),surfaces=model.surfaces.slice(),occluders=model.occluders.slice(),r=placeAndProbe(T,Scene,Town,world,model,m);assert.equal(r.supports.length,20);assert.ok(r.supports.every(p=>Math.abs(p.soleMinusFloor)<1e-6));assert.equal(r.roads.reduce((n,x)=>n+x.triangles,0),2022);assert.ok(r.minimumRoadGap>=.20);assert.equal(r.originalSpriteEnvelopeClearance.checkedCards,141);assert.ok(r.originalSpriteEnvelopeClearance.minimumGap>=.20);assert.equal(r.finiteWalkability.blocked,0);assert.equal(r.notRegisteredAsTownSurface,true);assert.equal(JSON.stringify(world),before);assert.deepEqual(model.surfaces,surfaces);assert.deepEqual(model.occluders,occluders);assert.equal(model.scene.userData.originalArtRevision,'placement-originals1');assert.equal(m.evaluate(1).clear,true);assert.deepEqual(m.group.scale.toArray(),[1,1,1]);m.dispose();model.dispose();});
test('all reused and new resources including the optional procedural texture dispose once, without affecting another instance',()=>{const a=build(T),b=build(T),texture=new T.Texture();a.addTexture(texture);assert.equal(a.inspect().budget.textures,1);const resources=Object.values(a.resources).flatMap(s=>[...s]);let count=0;for(const r of resources)r.addEventListener('dispose',()=>count++);a.dispose();a.dispose();assert.equal(count,resources.length);assert.equal(a.group.children.length,0);assert.throws(()=>a.reset(),/disposed/);assert.throws(()=>a.addTexture(new T.Texture()),/disposed/);assert.equal(b.disposed,false);b.setProgress(1);b.dispose();});
test('the frozen finite certificate and manifest bind the isolated source and bounded manual native/capture contract',()=>{const manifest=JSON.parse(fs.readFileSync(path.join(base,'input-manifest.json'))),certificate=JSON.parse(fs.readFileSync(path.join(base,'finite-contact-certificate.json'))),html=fs.readFileSync(path.join(base,'index.html'),'utf8'),viewer=fs.readFileSync(path.join(base,'viewer.mjs'),'utf8');assert.equal(manifest.unit_id,spec.unit);for(const f of manifest.files)assert.equal(sha(fs.readFileSync(path.join(base,f.path))),f.sha256);assert.equal(certificate.default.samples,21);assert.equal(certificate.default.allFinitePosesClear,true);assert.ok(certificate.rejections.every(x=>x.allFinitePosesClear===false));assert.equal(certificate.formal_test_count_claimed,0);for(const id of ['outside','inside','forward','reverse','progress','reset','focus','stage'])assert.ok(html.includes('id="'+id+'"'));assert.ok(viewer.includes('window.__mailSlotProof=Object.freeze'));assert.ok(viewer.includes("fetch('/__capture/slot'"));assert.ok(viewer.includes('setProgress'));assert.ok(!/localStorage|sessionStorage|\/api\//.test(viewer));assert.equal(manifest.normal_game_integration,false);assert.equal(manifest.new_Mesh_library_candidates,0);assert.equal(manifest.new_original_PNGs,0);});
